+/****************************************************************************
+ * BK7258 Armino mailbox backend over the Vela CP/AP RPMsg link.
+ *
+ * The imported Armino mailbox_channel.c and mb_ipc.c retain ownership of
+ * logical-channel, ACK, socket, port, CRC, and timeout state.  This file is
+ * only their physical mailbox backend: it serializes the authority's four
+ * 32-bit mailbox words over RPMsg and recreates a local payload address before
+ * invoking the authority receive callback.
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#ifdef CONFIG_BK7258_MB_IPC_RPMSG
+
+#include <errno.h>
+#include <stdbool.h>
+#include <stddef.h>
+#include <stdint.h>
+#include <string.h>
+
+#include <nuttx/rpmsg/rpmsg.h>
+#include <nuttx/spinlock.h>
+
+#include <common/bk_err.h>
+#include <driver/mailbox_channel.h>
+#include <driver/mailbox_types.h>
+
+#define BK7258_MB_RPMSG_NAME          "bk7258-mb-ipc"
+#define BK7258_MB_RPMSG_MAGIC         UINT32_C(0x4d425250) /* MBRP */
+#define BK7258_MB_RPMSG_VERSION       1
+#define BK7258_MB_RPMSG_FRAME_PAYLOAD 384
+#define BK7258_MB_RPMSG_MAX_PAYLOAD   4096
+#define BK7258_MB_RPMSG_RX_SLOTS      4
+
+/* These bit positions are the authority mb_chnl_hdr_t ABI, not a new Vela
+ * protocol.  Word 0 remains byte-for-byte authority mailbox_data_t.param0.
+ */
+
+#define BK7258_MB_HDR_CMD_MASK        UINT32_C(0x000000ff)
+#define BK7258_MB_HDR_ACK_BOX         UINT32_C(0x00001000)
+#define BK7258_MB_HDR_LOGICAL_SHIFT   24
+#define BK7258_MB_IPC_RSP_FLAG        UINT32_C(0x80)
+#define BK7258_MB_IPC_LOGICAL_ID      1
+
+struct __attribute__((packed)) bk7258_mb_rpmsg_hdr_s
+{
+  uint32_t magic;
+  uint16_t version;
+  uint8_t src_cpu;
+  uint8_t dst_cpu;
+  uint16_t total_len;
+  uint16_t offset;
+  uint16_t chunk_len;
+  uint16_t reserved;
+  uint32_t word[4];
+};
+
+struct bk7258_mb_rpmsg_slot_s
+{
+  bool used;
+  uint8_t src_cpu;
+  uint8_t dst_cpu;
+  uint8_t logical_chnl;
+  uint32_t word1;
+  uint16_t total_len;
+  uint16_t received;
+  uint32_t word[4];
+  uint8_t payload[BK7258_MB_RPMSG_MAX_PAYLOAD];
+};
+
+struct bk7258_mb_rpmsg_state_s
+{
+  struct rpmsg_endpoint ept;
+  mailbox_callback_t callback[2][2];
+  struct bk7258_mb_rpmsg_slot_s slot[BK7258_MB_RPMSG_RX_SLOTS];
+  spinlock_t lock;
+  bool registered;
+};
+
+static struct bk7258_mb_rpmsg_state_s g_bk7258_mb_rpmsg =
+{
+  .lock = SP_UNLOCKED,
+};
+
+_Static_assert(sizeof(mailbox_data_t) == 4 * sizeof(uint32_t),
+               "Armino mailbox ABI must remain four words");
+_Static_assert(sizeof(uintptr_t) == sizeof(uint32_t),
+               "BK7258 Armino mailbox payload pointers are 32-bit");
+_Static_assert(sizeof(struct bk7258_mb_rpmsg_hdr_s) == 32,
+               "RPMsg mailbox envelope layout changed");
+
+static uint8_t bk7258_mb_rpmsg_local_cpu(void)
+{
+#ifdef CONFIG_BK7258_COMPONENT_CP
+  return MAILBOX_CPU0;
+#else
+  return MAILBOX_CPU1;
+#endif
+}
+
+static uint8_t bk7258_mb_rpmsg_peer_cpu(void)
+{
+#ifdef CONFIG_BK7258_COMPONENT_CP
+  return MAILBOX_CPU1;
+#else
+  return MAILBOX_CPU0;
+#endif
+}
+
+static bool bk7258_mb_rpmsg_is_ipc(uint32_t word0)
+{
+  return (word0 & BK7258_MB_HDR_ACK_BOX) == 0 &&
+         (((word0 >> BK7258_MB_HDR_LOGICAL_SHIFT) & 0x0f) ==
+          BK7258_MB_IPC_LOGICAL_ID);
+}
+
+static bool bk7258_mb_rpmsg_words_match_role(const uint32_t word[4],
+                                              uint8_t src_cpu,
+                                              uint8_t dst_cpu)
+{
+  uint8_t logical_chnl = word[0] >> BK7258_MB_HDR_LOGICAL_SHIFT;
+
+  return GET_SRC_CPU_ID(logical_chnl) == src_cpu &&
+         GET_DST_CPU_ID(logical_chnl) == dst_cpu;
+}
+
+static struct bk7258_mb_rpmsg_slot_s *
+bk7258_mb_rpmsg_find_slot(uint8_t src_cpu, uint8_t dst_cpu,
+                           uint8_t logical_chnl, uint32_t word1)
+{
+  unsigned int i;
+
+  for (i = 0; i < BK7258_MB_RPMSG_RX_SLOTS; i++)
+    {
+      struct bk7258_mb_rpmsg_slot_s *slot = &g_bk7258_mb_rpmsg.slot[i];
+
+      if (slot->used && slot->src_cpu == src_cpu &&
+          slot->dst_cpu == dst_cpu && slot->logical_chnl == logical_chnl &&
+          slot->word1 == word1)
+        {
+          return slot;
+        }
+    }
+
+  return NULL;
+}
+
+static struct bk7258_mb_rpmsg_slot_s *
+bk7258_mb_rpmsg_alloc_slot(uint8_t src_cpu, uint8_t dst_cpu,
+                            uint8_t logical_chnl, uint32_t word1)
+{
+  unsigned int i;
+
+  for (i = 0; i < BK7258_MB_RPMSG_RX_SLOTS; i++)
+    {
+      struct bk7258_mb_rpmsg_slot_s *slot = &g_bk7258_mb_rpmsg.slot[i];
+
+      if (!slot->used)
+        {
+          memset(slot, 0, sizeof(*slot));
+          slot->used = true;
+          slot->src_cpu = src_cpu;
+          slot->dst_cpu = dst_cpu;
+          slot->logical_chnl = logical_chnl;
+          slot->word1 = word1;
+          return slot;
+        }
+    }
+
+  return NULL;
+}
+
+static void bk7258_mb_rpmsg_release_response_slot(uint32_t word0,
+                                                   uint32_t word1)
+{
+  uint8_t src_cpu;
+  uint8_t dst_cpu;
+  uint8_t src_port;
+  uint8_t dst_port;
+  uint8_t tag;
+  unsigned int i;
+
+  if ((word0 & BK7258_MB_IPC_RSP_FLAG) == 0)
+    {
+      return;
+    }
+
+  dst_port = word1 & 0x3f;
+  dst_cpu = (word1 >> 6) & 0x03;
+  src_port = (word1 >> 8) & 0x3f;
+  src_cpu = (word1 >> 14) & 0x03;
+  tag = (word1 >> 16) & 0xff;
+
+  for (i = 0; i < BK7258_MB_RPMSG_RX_SLOTS; i++)
+    {
+      struct bk7258_mb_rpmsg_slot_s *slot = &g_bk7258_mb_rpmsg.slot[i];
+      uint32_t incoming = slot->word1;
+
+      if (!slot->used || ((incoming >> 16) & 0xff) != tag ||
+          ((incoming >> 14) & 0x03) != dst_cpu ||
+          ((incoming >> 8) & 0x3f) != dst_port ||
+          ((incoming >> 6) & 0x03) != src_cpu ||
+          (incoming & 0x3f) != src_port)
+        {
+          continue;
+        }
+
+      memset(slot, 0, sizeof(*slot));
+      return;
+    }
+}
+
+static int bk7258_mb_rpmsg_ept_cb(struct rpmsg_endpoint *ept, void *data,
+                                  size_t len, uint32_t src, void *priv)
+{
+  struct bk7258_mb_rpmsg_hdr_s hdr;
+  mailbox_callback_t callback;
+  mailbox_data_t visible;
+  struct bk7258_mb_rpmsg_slot_s *slot;
+  irqstate_t flags;
+  uint8_t logical_chnl;
+  bool ipc;
+
+  (void)ept;
+  (void)src;
+  (void)priv;
+
+  if (len < sizeof(hdr))
+    {
+      return -EINVAL;
+    }
+
+  memcpy(&hdr, data, sizeof(hdr));
+  if (hdr.magic != BK7258_MB_RPMSG_MAGIC ||
+      hdr.version != BK7258_MB_RPMSG_VERSION ||
+      hdr.src_cpu != bk7258_mb_rpmsg_peer_cpu() ||
+      hdr.dst_cpu != bk7258_mb_rpmsg_local_cpu() ||
+      hdr.chunk_len > BK7258_MB_RPMSG_FRAME_PAYLOAD ||
+      hdr.total_len > BK7258_MB_RPMSG_MAX_PAYLOAD ||
+      hdr.offset > hdr.total_len || hdr.chunk_len > hdr.total_len - hdr.offset ||
+      len != sizeof(hdr) + hdr.chunk_len ||
+      !bk7258_mb_rpmsg_words_match_role(hdr.word, hdr.src_cpu, hdr.dst_cpu))
+    {
+      return -EINVAL;
+    }
+
+  logical_chnl = hdr.word[0] >> BK7258_MB_HDR_LOGICAL_SHIFT;
+  ipc = bk7258_mb_rpmsg_is_ipc(hdr.word[0]);
+  if (!ipc && (hdr.total_len != 0 || hdr.offset != 0 || hdr.chunk_len != 0))
+    {
+      return -EINVAL;
+    }
+
+  flags = spin_lock_irqsave(&g_bk7258_mb_rpmsg.lock);
+  callback = g_bk7258_mb_rpmsg.callback[hdr.src_cpu][hdr.dst_cpu];
+  if (callback == NULL)
+    {
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+      return -ENOTCONN;
+    }
+
+  if (!ipc || hdr.total_len == 0)
+    {
+      memcpy(&visible, hdr.word, sizeof(visible));
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+      callback(&visible);
+      return 0;
+    }
+
+  slot = bk7258_mb_rpmsg_find_slot(hdr.src_cpu, hdr.dst_cpu, logical_chnl,
+                                   hdr.word[1]);
+  if (hdr.offset == 0)
+    {
+      if (slot != NULL)
+        {
+          memset(slot, 0, sizeof(*slot));
+        }
+
+      slot = bk7258_mb_rpmsg_alloc_slot(hdr.src_cpu, hdr.dst_cpu,
+                                        logical_chnl, hdr.word[1]);
+      if (slot != NULL)
+        {
+          slot->total_len = hdr.total_len;
+          memcpy(slot->word, hdr.word, sizeof(slot->word));
+        }
+    }
+
+  if (slot == NULL || slot->total_len != hdr.total_len ||
+      slot->received != hdr.offset ||
+      memcmp(slot->word, hdr.word, sizeof(slot->word)) != 0)
+    {
+      if (slot != NULL)
+        {
+          memset(slot, 0, sizeof(*slot));
+        }
+
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+      return -EPROTO;
+    }
+
+  memcpy(slot->payload + hdr.offset, (const uint8_t *)data + sizeof(hdr),
+         hdr.chunk_len);
+  slot->received += hdr.chunk_len;
+  if (slot->received != slot->total_len)
+    {
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+      return 0;
+    }
+
+  memcpy(&visible, slot->word, sizeof(visible));
+  visible.param3 = (uint32_t)(uintptr_t)slot->payload;
+  spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+
+  callback(&visible);
+  return 0;
+}
+
+static void bk7258_mb_rpmsg_device_created(struct rpmsg_device *rdev,
+                                            void *priv)
+{
+  struct bk7258_mb_rpmsg_state_s *state = priv;
+  irqstate_t flags;
+  int ret;
+
+  if (strcmp(rpmsg_get_cpuname(rdev),
+#ifdef CONFIG_BK7258_COMPONENT_CP
+             "ap"
+#else
+             "cp"
+#endif
+             ) != 0)
+    {
+      return;
+    }
+
+  flags = spin_lock_irqsave(&state->lock);
+  if (state->ept.priv != NULL)
+    {
+      spin_unlock_irqrestore(&state->lock, flags);
+      return;
+    }
+
+  state->ept.priv = state;
+  spin_unlock_irqrestore(&state->lock, flags);
+
+  ret = rpmsg_create_ept(&state->ept, rdev, BK7258_MB_RPMSG_NAME,
+                         RPMSG_ADDR_ANY, RPMSG_ADDR_ANY,
+                         bk7258_mb_rpmsg_ept_cb, NULL);
+  if (ret < 0)
+    {
+      flags = spin_lock_irqsave(&state->lock);
+      state->ept.priv = NULL;
+      spin_unlock_irqrestore(&state->lock, flags);
+    }
+}
+
+static void bk7258_mb_rpmsg_device_destroy(struct rpmsg_device *rdev,
+                                            void *priv)
+{
+  struct bk7258_mb_rpmsg_state_s *state = priv;
+
+  if (state->ept.priv != NULL &&
+      strcmp(rpmsg_get_cpuname(rdev),
+#ifdef CONFIG_BK7258_COMPONENT_CP
+             "ap"
+#else
+             "cp"
+#endif
+             ) == 0)
+    {
+      rpmsg_destroy_ept(&state->ept);
+      state->ept.priv = NULL;
+    }
+}
+
+bk_err_t bk_mailbox_init(void)
+{
+  irqstate_t flags;
+  int ret;
+
+  flags = spin_lock_irqsave(&g_bk7258_mb_rpmsg.lock);
+  if (g_bk7258_mb_rpmsg.registered)
+    {
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+      return BK_OK;
+    }
+
+  g_bk7258_mb_rpmsg.registered = true;
+  spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+
+  ret = rpmsg_register_callback(&g_bk7258_mb_rpmsg,
+                                bk7258_mb_rpmsg_device_created,
+                                bk7258_mb_rpmsg_device_destroy, NULL, NULL);
+  if (ret < 0)
+    {
+      flags = spin_lock_irqsave(&g_bk7258_mb_rpmsg.lock);
+      g_bk7258_mb_rpmsg.registered = false;
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+      return BK_ERR_MAILBOX_NOT_INIT;
+    }
+
+  return BK_OK;
+}
+
+bk_err_t bk_mailbox_deinit(void)
+{
+  irqstate_t flags;
+
+  flags = spin_lock_irqsave(&g_bk7258_mb_rpmsg.lock);
+  if (!g_bk7258_mb_rpmsg.registered)
+    {
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+      return BK_OK;
+    }
+
+  g_bk7258_mb_rpmsg.registered = false;
+  spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+  rpmsg_unregister_callback(&g_bk7258_mb_rpmsg,
+                            bk7258_mb_rpmsg_device_created,
+                            bk7258_mb_rpmsg_device_destroy, NULL, NULL);
+  return BK_OK;
+}
+
+bk_err_t bk_mailbox_set_param(mailbox_data_t *data, uint32_t p0,
+                              uint32_t p1, uint32_t p2, uint32_t p3)
+{
+  if (data == NULL)
+    {
+      return BK_ERR_PARAM;
+    }
+
+  data->param0 = p0;
+  data->param1 = p1;
+  data->param2 = p2;
+  data->param3 = p3;
+  return BK_OK;
+}
+
+bk_err_t bk_mailbox_recv_callback_register(mailbox_endpoint_t src,
+                                            mailbox_endpoint_t dst,
+                                            mailbox_callback_t callback)
+{
+  irqstate_t flags;
+
+  if (src > MAILBOX_CPU1 || dst != bk7258_mb_rpmsg_local_cpu() ||
+      src != bk7258_mb_rpmsg_peer_cpu() || callback == NULL)
+    {
+      return BK_ERR_MAILBOX_SRC_DST;
+    }
+
+  flags = spin_lock_irqsave(&g_bk7258_mb_rpmsg.lock);
+  g_bk7258_mb_rpmsg.callback[src][dst] = callback;
+  spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+  return BK_OK;
+}
+
+bk_err_t bk_mailbox_recv_callback_unregister(mailbox_endpoint_t src,
+                                              mailbox_endpoint_t dst)
+{
+  irqstate_t flags;
+
+  if (src > MAILBOX_CPU1 || dst != bk7258_mb_rpmsg_local_cpu() ||
+      src != bk7258_mb_rpmsg_peer_cpu())
+    {
+      return BK_ERR_MAILBOX_SRC_DST;
+    }
+
+  flags = spin_lock_irqsave(&g_bk7258_mb_rpmsg.lock);
+  g_bk7258_mb_rpmsg.callback[src][dst] = NULL;
+  spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+  return BK_OK;
+}
+
+bk_err_t bk_mailbox_ready(mailbox_endpoint_t src, mailbox_endpoint_t dst,
+                          uint32_t box_id)
+{
+  (void)box_id;
+
+  if (src != bk7258_mb_rpmsg_local_cpu() ||
+      dst != bk7258_mb_rpmsg_peer_cpu() ||
+      !is_rpmsg_ept_ready(&g_bk7258_mb_rpmsg.ept))
+    {
+      return BK_ERR_MAILBOX_TIMEOUT;
+    }
+
+  return BK_OK;
+}
+
+bk_err_t bk_mailbox_send(mailbox_data_t *data, mailbox_endpoint_t src,
+                         mailbox_endpoint_t dst, void *arg)
+{
+  struct bk7258_mb_rpmsg_hdr_s hdr;
+  uint8_t frame[sizeof(hdr) + BK7258_MB_RPMSG_FRAME_PAYLOAD];
+  const uint8_t *payload = NULL;
+  uint32_t word[4];
+  uint16_t total_len = 0;
+  uint16_t offset = 0;
+  bool ipc;
+
+  (void)arg;
+
+  if (data == NULL || src != bk7258_mb_rpmsg_local_cpu() ||
+      dst != bk7258_mb_rpmsg_peer_cpu())
+    {
+      return BK_ERR_MAILBOX_SRC_DST;
+    }
+
+  memcpy(word, data, sizeof(word));
+  if (!bk7258_mb_rpmsg_words_match_role(word, src, dst) ||
+      !is_rpmsg_ept_ready(&g_bk7258_mb_rpmsg.ept))
+    {
+      return BK_ERR_MAILBOX_TIMEOUT;
+    }
+
+  ipc = bk7258_mb_rpmsg_is_ipc(word[0]);
+  if (ipc)
+    {
+      total_len = word[2] & UINT32_C(0xffff);
+      payload = (const uint8_t *)(uintptr_t)word[3];
+      if (total_len > BK7258_MB_RPMSG_MAX_PAYLOAD ||
+          (total_len != 0 && payload == NULL))
+        {
+          return BK_ERR_PARAM;
+        }
+    }
+
+  do
+    {
+      uint16_t chunk_len = total_len - offset;
+      int ret;
+
+      if (chunk_len > BK7258_MB_RPMSG_FRAME_PAYLOAD)
+        {
+          chunk_len = BK7258_MB_RPMSG_FRAME_PAYLOAD;
+        }
+
+      memset(&hdr, 0, sizeof(hdr));
+      hdr.magic = BK7258_MB_RPMSG_MAGIC;
+      hdr.version = BK7258_MB_RPMSG_VERSION;
+      hdr.src_cpu = src;
+      hdr.dst_cpu = dst;
+      hdr.total_len = total_len;
+      hdr.offset = offset;
+      hdr.chunk_len = chunk_len;
+      memcpy(hdr.word, word, sizeof(word));
+      memcpy(frame, &hdr, sizeof(hdr));
+      if (chunk_len != 0)
+        {
+          memcpy(frame + sizeof(hdr), payload + offset, chunk_len);
+        }
+
+      /* Do not let an authority START/END request block beyond its own
+       * 5 ms ACK budget. A full RPMsg ring is reported as a mailbox timeout
+       * and the unchanged authority code decides how to handle that error. */
+      ret = rpmsg_send_offchannel_raw(&g_bk7258_mb_rpmsg.ept,
+                                      g_bk7258_mb_rpmsg.ept.addr,
+                                      g_bk7258_mb_rpmsg.ept.dest_addr,
+                                      frame, sizeof(hdr) + chunk_len, false);
+      if (ret < 0)
+        {
+          return BK_ERR_MAILBOX_TIMEOUT;
+        }
+
+      offset += chunk_len;
+    }
+  while (offset < total_len);
+
+  if (ipc)
+    {
+      irqstate_t flags = spin_lock_irqsave(&g_bk7258_mb_rpmsg.lock);
+      bk7258_mb_rpmsg_release_response_slot(word[0], word[1]);
+      spin_unlock_irqrestore(&g_bk7258_mb_rpmsg.lock, flags);
+    }
+
+  return BK_OK;
+}
+
+#endif /* CONFIG_BK7258_MB_IPC_RPMSG */
