+  memcpy(slot->payload + wire.offset, (const uint8_t *)data + sizeof(wire),
+         wire.chunk_len);
+  slot->received += wire.chunk_len;
+  if (slot->received != slot->total_len)
+    {
+      spin_unlock_irqrestore(&g_bk_mb.lock, flags);
+      return 0;
+    }
