+  memcpy(&visible, slot->word, sizeof(visible));
+  visible.param3 = (uint32_t)(uintptr_t)slot->payload;
+  spin_unlock_irqrestore(&g_bk_mb.lock, flags);
+  callback(&visible);
+  return 0;
+}
