+{
+  if (src != bk_mb_peer_cpu() || dst != bk_mb_local_cpu())
+    {
+      return BK_ERR_MAILBOX_SRC_DST;
+    }
+
+  g_bk_mb.callback[src][dst] = NULL;
+  return BK_OK;
+}
